14	// maxDocBytes caps how much of an enrichment document (AGENTS.md, README.md)
15	// the detail endpoint returns, so a huge file cannot bloat a response.
16	const maxDocBytes = 128 * 1024
17	
18	// apiServer holds the request-independent state for the JSON API.
19	type apiServer struct {
20		root    string
21		version string
22	}
23	
24	// fileDoc is a text document surfaced in an integration's detail view.
25	type fileDoc struct {
26		Name    string `json:"name"`
27		Content string `json:"content"`
28	}
29	
30	// integrationSummary is a scaffold entry plus the coordinates the sidebar
31	// tree groups by: Name is the directory that carries the .intropy record,
32	// System is that directory's parent and Domain the system's parent. System
33	// is empty when the integration sits directly under the workspace root, and
34	// Domain is empty when the system does.
35	type integrationSummary struct {
36		template.ScaffoldEntry
37		Name   string `json:"name"`
38		System string `json:"system,omitempty"`
39		Domain string `json:"domain,omitempty"`
40	}
41	
42	// integrationDetail is a single integration plus best-effort, on-disk
43	// enrichment. Every enrichment field is optional and absent when the
44	// corresponding file or directory does not exist.
45	type integrationDetail struct {
46		integrationSummary
47		Agents         *fileDoc `json:"agents,omitempty"`
48		Readme         *fileDoc `json:"readme,omitempty"`
49		DaprComponents []string `json:"daprComponents,omitempty"`
50		PipelineSteps  []string `json:"pipelineSteps,omitempty"`
