53	// newHandler wires the API routes and the SPA static handler onto a mux.
54	func newHandler(root, version string) (http.Handler, error) {
55		api := &apiServer{root: root, version: version}
56		static, err := staticHandler()
57		if err != nil {
58			return nil, err
59		}
60	
61		mux := http.NewServeMux()
62		mux.HandleFunc("GET /api/health", api.health)
63		mux.HandleFunc("GET /api/integrations", api.listIntegrations)
64		mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
65		mux.HandleFunc("GET /api/flow", api.flow)
66		mux.Handle("/", static)
67		return mux, nil
68	}
