151	// enrich reads optional on-disk context for an integration. The entry's Path
152	// is already usable from the process working directory (see ListScaffolds), so
153	// it doubles as the project directory.
154	func (s *apiServer) enrich(e template.ScaffoldEntry) integrationDetail {
155		dir := e.Path
156		return integrationDetail{
157			integrationSummary: s.summarize(e),
158			Agents:             readDoc(dir, "AGENTS.md"),
159			Readme:             readDoc(dir, "README.md"),
160			DaprComponents:     listNames(filepath.Join(dir, "local", "dapr-components")),
161			PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
162		}
163	}
164	
165	// readDoc returns the named text file's (possibly truncated) contents, or nil
166	// if it is absent or unreadable.
167	func readDoc(dir, name string) *fileDoc {
168		data, err := os.ReadFile(filepath.Join(dir, name))
169		if err != nil {
170			return nil
171		}
172		if len(data) > maxDocBytes {
173			data = data[:maxDocBytes]
174		}
175		return &fileDoc{Name: name, Content: string(data)}
176	}
177	
178	// listNames returns the sorted base names of the files directly under dir, or
179	// nil if dir is absent or unreadable.
180	func listNames(dir string) []string {
181		ents, err := os.ReadDir(dir)
182		if err != nil {
183			return nil
184		}
185		var names []string
186		for _, ent := range ents {
187			if !ent.IsDir() {
188				names = append(names, ent.Name())
189			}
190		}
191		sort.Strings(names)
192		return names
193	}
