195	func writeJSON(w http.ResponseWriter, status int, v any) {
196		w.Header().Set("Content-Type", "application/json; charset=utf-8")
197		w.WriteHeader(status)
198		enc := json.NewEncoder(w)
199		enc.SetIndent("", "  ")
200		_ = enc.Encode(v)
201	}
202	
203	func writeError(w http.ResponseWriter, status int, msg string) {
204		writeJSON(w, status, map[string]string{"error": msg})
205	}
