import { useEffect, useMemo, useRef, useState } from 'react'
import { ExpandMoreIcon, SearchIcon } from '../icons'

export interface ComboOption {
  value: string
  label: string
  count?: number
}

interface Props {
  value: string | null
  options: ComboOption[]
  onChange: (value: string) => void
  placeholder?: string
}

// Combobox is a small searchable single-select. It intentionally avoids a
// dependency: a trigger button that opens a filterable list, closing on
// outside-click or Escape. Used by FlowView to pick which system to show.
export function Combobox({ value, options, onChange, placeholder }: Props) {
  const [open, setOpen] = useState(false)
  const [query, setQuery] = useState('')
  const rootRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const current = options.find((o) => o.value === value) ?? null

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return options
    return options.filter((o) => o.label.toLowerCase().includes(q))
  }, [options, query])

  // Close on outside click.
  useEffect(() => {
    if (!open) return
    function onDoc(e: MouseEvent) {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    document.addEventListener('mousedown', onDoc)
    return () => document.removeEventListener('mousedown', onDoc)
  }, [open])

  // Focus the filter input when the list opens.
  useEffect(() => {
    if (open) inputRef.current?.focus()
    else setQuery('')
  }, [open])

  function pick(v: string) {
    onChange(v)
    setOpen(false)
  }

  return (
    <div className="combo" ref={rootRef}>
      <button
        type="button"
        className="combo-trigger"
        onClick={() => setOpen((o) => !o)}
        aria-haspopup="listbox"
        aria-expanded={open}
      >
        <span className={`combo-value${current ? '' : ' placeholder'}`}>
          {current ? current.label : (placeholder ?? 'Select…')}
        </span>
        <ExpandMoreIcon className="combo-caret" aria-hidden />
      </button>

      {open && (
        <div className="combo-pop">
          <div className="combo-search">
            <SearchIcon className="combo-search-icon" aria-hidden />
            <input
              ref={inputRef}
              className="combo-input"
              value={query}
              placeholder="Search systems…"
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Escape') setOpen(false)
                if (e.key === 'Enter' && filtered.length > 0) pick(filtered[0].value)
              }}
            />
          </div>
          <ul className="combo-list" role="listbox">
            {filtered.length === 0 ? (
              <li className="combo-empty">No matches</li>
            ) : (
              filtered.map((o) => (
                <li key={o.value}>
                  <button
                    type="button"
                    role="option"
                    aria-selected={o.value === value}
                    className={`combo-option${o.value === value ? ' active' : ''}`}
                    onClick={() => pick(o.value)}
                  >
                    <span className="combo-option-label">{o.label}</span>
                    {o.count != null && <span className="combo-option-count">{o.count}</span>}
                  </button>
                </li>
              ))
            )}
          </ul>
        </div>
      )}
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import {
  Background,
  Controls,
  Handle,
  MarkerType,
  MiniMap,
  Position,
  ReactFlow,
  useNodesState,
  type Edge,
  type Node,
  type NodeProps,
} from '@xyflow/react'
import '@xyflow/react/dist/style.css'
import { api, type DaprComponent, type IntegrationDetail } from '../api'
import {
  CloudIcon,
  DatabaseIcon,
  HardDriveIcon,
  HubIcon,
  MemoryIcon,
  RouteIcon,
} from '../icons'
import { Combobox, type ComboOption } from './Combobox'

interface Props {
  selected: string | null
  onSelect: (path: string) => void
}

// Layout geometry. The layout is deterministic: integration cards flow in a
// grid inside the system boundary, shared infra (pub/sub, databases) sits in a
// row beneath them still inside the boundary, and external sinks (disk,
// bindings) stack outside it to the right.
const NODE_W = 300
const NODE_H = 172
const COL_GAP = 28
const ROW_GAP = 28
const COLS = 2
const GROUP_HEADER = 44
const GROUP_PAD = 20
const INFRA_W = 200
const INFRA_H = 76
const INFRA_GAP = 32
const EXT_W = 184
const EXT_H = 72
const EXT_GAP = 96
const EXT_VGAP = 24

const WORKSPACE_KEY = '__workspace__'

interface IntNodeData extends Record<string, unknown> {
  name: string
  template: string
  steps: string[]
  selected: boolean
}

interface GroupNodeData extends Record<string, unknown> {
  title: string
  count: number
}

interface InfraNodeData extends Record<string, unknown> {
  name: string
  type: string
  category: DaprComponent['category']
}

interface ExtNodeData extends Record<string, unknown> {
  name: string
  type: string
}

// systemKey/systemLabel identify a system by its domain/system folder pair so
// two different domains that reuse a system name stay distinct. Integrations
// scaffolded at the workspace root fall under a "Workspace" pseudo-system.
function systemKey(it: IntegrationDetail): string {
  return [it.domain, it.system].filter(Boolean).join('/') || WORKSPACE_KEY
}

function systemLabel(it: IntegrationDetail): string {
  return [it.domain, it.system].filter(Boolean).join(' / ') || 'Workspace'
}

export function FlowView({ selected, onSelect }: Props) {
  const [graph, setGraph] = useState<IntegrationDetail[] | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [system, setSystem] = useState<string | null>(null)
  const [nodes, setNodes, onNodesChange] = useNodesState<Node>([])

  useEffect(() => {
    api
      .flow()
      .then(setGraph)
      .catch((e: unknown) => setError(e instanceof Error ? e.message : String(e)))
  }, [])

  // The dropdown lists every system present, with an integration count.
  const systems = useMemo<ComboOption[]>(() => {
    if (!graph) return []
    const map = new Map<string, ComboOption>()
    for (const it of graph) {
      const key = systemKey(it)
      const opt = map.get(key) ?? { value: key, label: systemLabel(it), count: 0 }
      opt.count = (opt.count ?? 0) + 1
      map.set(key, opt)
    }
    return [...map.values()].sort((a, b) => a.label.localeCompare(b.label))
  }, [graph])

  // Default to the first system once data lands.
  useEffect(() => {
    if (system === null && systems.length > 0) setSystem(systems[0].value)
  }, [systems, system])

  const items = useMemo(
    () => (graph && system ? graph.filter((it) => systemKey(it) === system) : []),
    [graph, system],
  )

  const built = useMemo(() => buildGraph(items), [items])
  useEffect(() => setNodes(built.nodes), [built, setNodes])

  // Reflect the shared selection without disturbing dragged positions.
  useEffect(() => {
    setNodes((ns) =>
      ns.map((n) =>
        n.type === 'integration'
          ? { ...n, data: { ...n.data, selected: n.id === selected } }
          : n,
      ),
    )
  }, [selected, setNodes])

  if (error) {
    return <div className="banner error">{error}</div>
  }
  if (!graph) {
    return <p className="empty">Loading…</p>
  }
  if (graph.length === 0) {
    return <p className="empty">No integrations to visualise.</p>
  }

  return (
    <div className="flow-view">
      <div className="flow-toolbar">
        <span className="flow-toolbar-label">System</span>
        <Combobox
          value={system}
          options={systems}
          onChange={setSystem}
          placeholder="Select a system…"
        />
      </div>
      <div className="flow-canvas">
        <ReactFlow
          key={system ?? ''}
          nodes={nodes}
          edges={built.edges}
          onNodesChange={onNodesChange}
          nodeTypes={NODE_TYPES}
          colorMode="system"
          fitView
          fitViewOptions={{ padding: 0.2 }}
          minZoom={0.3}
          proOptions={{ hideAttribution: true }}
          onNodeClick={(_, node) => {
            if (node.type === 'integration') onSelect(node.id)
          }}
        >
          <Background gap={20} />
          <Controls showInteractive={false} />
          <MiniMap pannable zoomable />
        </ReactFlow>
      </div>
    </div>
  )
}

// buildGraph turns one system's integrations into a single dashed boundary
// containing the integration cards and their shared infra, plus external sink
// nodes outside the boundary, wired with edges.
function buildGraph(items: IntegrationDetail[]): { nodes: Node[]; edges: Edge[] } {
  if (items.length === 0) return { nodes: [], edges: [] }

  const groupId = 'system'
  const n = items.length
  const cols = Math.max(1, Math.min(COLS, n))
  const rows = Math.ceil(n / cols)
  const gridWidth = cols * NODE_W + (cols - 1) * COL_GAP

  // Shared infra (pub/sub + state) deduped by category+name across the system.
  const infra = new Map<string, InfraNodeData>()
  for (const it of items) {
    for (const c of it.components ?? []) {
      if (c.category === 'pubsub' || c.category === 'state') {
        infra.set(`infra:${c.category}:${c.name}`, {
          name: c.name,
          type: c.type,
          category: c.category,
        })
      }
    }
  }
  const infraEntries = [...infra.entries()].sort((a, b) => a[0].localeCompare(b[0]))

  const contentTop = GROUP_HEADER
  const intBlockH = rows * NODE_H + (rows - 1) * ROW_GAP

  // Infra wraps within the integration grid width, in its own row(s) below.
  const infraCols = Math.max(1, Math.floor((gridWidth + COL_GAP) / (INFRA_W + COL_GAP)))
  const infraRows = infraEntries.length ? Math.ceil(infraEntries.length / infraCols) : 0
  const infraTop = contentTop + intBlockH + (infraEntries.length ? INFRA_GAP : 0)
  const infraBlockH = infraRows ? infraRows * INFRA_H + (infraRows - 1) * ROW_GAP : 0

  const groupWidth = GROUP_PAD * 2 + gridWidth
  const groupHeight =
    contentTop + intBlockH + (infraEntries.length ? INFRA_GAP + infraBlockH : 0) + GROUP_PAD

  const nodes: Node[] = []
  const edges: Edge[] = []

  nodes.push({
    id: groupId,
    type: 'group',
    position: { x: 0, y: 0 },
    data: { title: items[0] ? systemLabel(items[0]) : 'System', count: n } satisfies GroupNodeData,
    style: { width: groupWidth, height: groupHeight },
    draggable: false,
    selectable: false,
  })

  // Integration cards.
  items.forEach((it, i) => {
    const col = i % cols
    const row = Math.floor(i / cols)
    nodes.push({
      id: it.path,
      type: 'integration',
      parentId: groupId,
      extent: 'parent',
      position: {
        x: GROUP_PAD + col * (NODE_W + COL_GAP),
        y: contentTop + row * (NODE_H + ROW_GAP),
      },
      data: {
        name: it.name,
        template: it.template,
        steps: it.pipelineSteps ?? [],
        selected: false,
      } satisfies IntNodeData,
    })
  })

  // Shared infra row, inside the boundary.
  infraEntries.forEach(([id, data], i) => {
    const col = i % infraCols
    const row = Math.floor(i / infraCols)
    nodes.push({
      id,
      type: 'infra',
      parentId: groupId,
      extent: 'parent',
      position: {
        x: GROUP_PAD + col * (INFRA_W + COL_GAP),
        y: infraTop + row * (INFRA_H + ROW_GAP),
      },
      data,
    })
  })

  // External sinks (bindings), outside the boundary to the right. Kept
  // per-integration since each writes its own destination.
  let extIndex = 0
  for (const it of items) {
    for (const c of it.components ?? []) {
      if (c.category !== 'binding') continue
      const extId = `ext:${it.path}:${c.name}`
      nodes.push({
        id: extId,
        type: 'external',
        position: {
          x: groupWidth + EXT_GAP,
          y: contentTop + extIndex * (EXT_H + EXT_VGAP),
        },
        data: { name: c.name, type: c.type } satisfies ExtNodeData,
        draggable: true,
      })
      edges.push({
        id: `e:${it.path}:ext:${extId}`,
        source: it.path,
        sourceHandle: 'ext',
        target: extId,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
      })
      extIndex++
    }
  }

  // Integration -> shared infra edges.
  for (const it of items) {
    for (const c of it.components ?? []) {
      if (c.category !== 'pubsub' && c.category !== 'state') continue
      const infraId = `infra:${c.category}:${c.name}`
      edges.push({
        id: `e:${it.path}:infra:${infraId}`,
        source: it.path,
        sourceHandle: 'infra',
        target: infraId,
        targetHandle: 'in',
        className: 'rf-edge-infra',
      })
    }
  }

  return { nodes, edges }
}

function GroupNode({ data }: NodeProps) {
  const { title, count } = data as GroupNodeData
  return (
    <div className="rf-group">
      <div className="rf-group-title">
        <span>{title}</span>
        <span className="count">{count}</span>
      </div>
    </div>
  )
}

function IntegrationNode({ data }: NodeProps) {
  const { name, template, steps, selected } = data as IntNodeData
  return (
    <div className={`rf-int${selected ? ' selected' : ''}`}>
      <div className="rf-int-head">
        <MemoryIcon className="rf-int-icon" aria-hidden />
        <span className="rf-int-name">{name}</span>
        {template && <span className="rf-int-tag">{template}</span>}
      </div>

      <div className="rf-int-row">
        <RouteIcon className="rf-int-row-icon" aria-hidden />
        {steps.length === 0 ? (
          <span className="rf-int-empty">no steps</span>
        ) : (
          <div className="rf-int-chips">
            {steps.map((s) => (
              <span key={s} className="rf-chip">
                {stepName(s)}
              </span>
            ))}
          </div>
        )}
      </div>

      <Handle type="source" position={Position.Bottom} id="infra" />
      <Handle type="source" position={Position.Right} id="ext" />
    </div>
  )
}

function InfraNode({ data }: NodeProps) {
  const { name, type, category } = data as InfraNodeData
  const Icon = category === 'state' ? DatabaseIcon : HubIcon
  const kind = category === 'state' ? 'database' : 'pub/sub'
  return (
    <div className={`rf-infra ${category}`}>
      <Handle type="target" position={Position.Top} id="in" />
      <Icon className="rf-infra-icon" aria-hidden />
      <div className="rf-infra-text">
        <span className="rf-infra-name">{name}</span>
        <span className="rf-infra-kind" title={type}>
          {kind}
        </span>
      </div>
    </div>
  )
}

function ExternalNode({ data }: NodeProps) {
  const { name, type } = data as ExtNodeData
  const isDisk = /localstorage|localfile|disk|file/i.test(type)
  const Icon = isDisk ? HardDriveIcon : CloudIcon
  return (
    <div className="rf-ext">
      <Handle type="target" position={Position.Left} id="in" />
      <Icon className="rf-ext-icon" aria-hidden />
      <div className="rf-ext-text">
        <span className="rf-ext-name">{name}</span>
        <span className="rf-ext-kind" title={type}>
          {isDisk ? 'disk' : 'external'}
        </span>
      </div>
    </div>
  )
}

